*/
scwin.loadCapital = function (bzProcsNo, clmInstSeq, comNm, invstChgTpCd, invstDd, invstSaleShrs, pershrInvstSaleAmt, stkNm, incdecRsn) {
    /* sdd-asis-lifecycle:begin fn_LoadCapital — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent("comNm").setValue(comNm);
    (((scwin.form.invstChgTpCd) && (scwin.form.invstChgTpCd).setValue) ? (scwin.form.invstChgTpCd).setValue(invstChgTpCd) : void 0);
    $c.util.getComponent("invstDd").setValue($c.date.dateUnFormat(invstDd));
    scwin.form.invstSaleShrs.value = $c.num.formatNumber(invstSaleShrs);
    scwin.form.pershrInvstSaleAmt.value = $c.num.formatNumber(pershrInvstSaleAmt);
    (((scwin.form.stkNm) && (scwin.form.stkNm).setValue) ? (scwin.form.stkNm).setValue(stkNm) : void 0);
    (((scwin.form.incdecRsn) && (scwin.form.incdecRsn).setValue) ? (scwin.form.incdecRsn).setValue(incdecRsn) : void 0);
    /* sdd-asis-lifecycle:end */
};


